'use strict';
(() => {
const F=window.AdminFixtures, KEY='yx.demo.admin.product.v3', identities=F.identities;
let S=F.seed(), storageFailed=false, parseFailed=false;
try {const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(parsed.version===3)S=parsed;else parseFailed=true;}}catch(e){storageFailed=true;}
let ui={mode:'normal',q:'',filter:'全部',page:1,dirty:false}, undo=null, currentId='', modalAction=null, modalSubject='', toastTimer;
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), now=()=>new Date().toLocaleString('zh-CN',{hour12:false}), clone=v=>JSON.parse(JSON.stringify(v));
const release=c=>c.releaseStatus||(c.published?(c.blocked.includes(c.published)?'强制下架':c.status==='已下架'?'已下架':'已发布'):'未发布');
const who=()=>identities.find(x=>x.id===S.identity)||identities[4], name=id=>identities.find(x=>x.id===id)?.name||'未分配';
const routes={
 login:['管理登录','身份验证','identity'],dash:['运营工作台','OVERVIEW','dashboard'],content:['内容资产','CONTENT / LIBRARY','content'],editor:['内容编辑','CONTENT / EDITOR','content'],contentdetail:['内容详情','CONTENT / DETAIL','content'],review:['双人审核','CONTENT / REVIEW','review'],reviewdetail:['审核详情','CONTENT / DECISION','review'],publish:['发布管理','CONTENT / RELEASE','publish'],versions:['版本与回滚','CONTENT / VERSION','publish'],media:['媒体资源','CONTENT / MEDIA','media'],upload:['上传与绑定','CONTENT / UPLOAD','media'],governance:['风险案件','TRUST / CASES','governance'],riskdetail:['风险分诊','TRUST / TRIAGE','governance'],reports:['举报核查','TRUST / REPORTS','governance'],reportdetail:['举报详情','TRUST / EVIDENCE','governance'],students:['学员管理','LEARNER / DIRECTORY','students'],studentdetail:['学员档案','LEARNER / PROFILE','students'],studentaction:['学员处理','LEARNER / ACTION','students'],tickets:['客服工单','SUPPORT / INBOX','tickets'],ticketdetail:['工单详情','SUPPORT / CONVERSATION','tickets'],orders:['商城订单','COMMERCE / ORDERS','orders'],orderdetail:['订单详情','COMMERCE / DETAIL','orders'],refunds:['退款审批','COMMERCE / REFUNDS','refunds'],refunddetail:['退款详情','COMMERCE / APPROVAL','refunds'],reconcile:['对账与权益','COMMERCE / RECONCILIATION','orders'],privacy:['隐私请求','PRIVACY / REQUESTS','privacy'],privacydetail:['隐私请求详情','PRIVACY / LIFECYCLE','privacy'],audit:['审计日志','PLATFORM / AUDIT','audit'],auditdetail:['审计详情','PLATFORM / TRACE','audit'],observability:['运行观测','PLATFORM / OBSERVE','observability'],recovery:['恢复任务','PLATFORM / RECOVERY','observability'],permissions:['权限矩阵','PLATFORM / ACCESS','permissions'],identity:['身份与设置','SETTINGS / ACCOUNT','identity']};
const aliases={draft:'content',gov:'governance',me:'identity',cs:'tickets',shop:'orders',perm:'permissions',obs:'observability',adraft:'editor',areview:'review',apublish:'publish'};
function route(){let [r,id]=(location.hash.replace(/^#\/?/,'')||'dash').split('/');r=aliases[r]||r;currentId=decodeURIComponent(id||'');return routes[r]?r:'dash';}
function allowed(scope){return ['identity','dashboard'].includes(scope)||who().scopes.includes(scope);}
function go(r,id=''){if(ui.dirty&&!confirm('当前表单还有未保存内容。确定离开吗？'))return;ui.dirty=false;ui.q='';ui.filter='全部';ui.page=1;ui.mode='normal';const target='#/'+r+(id?'/'+encodeURIComponent(id):'');if(location.hash===target)render();else location.hash=target;}
function notify(msg){const n=$('#toast');n.textContent=msg;n.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>n.classList.remove('show'),3500);}
function transact(action,subject,reason,fn){const before=clone(S);try{if(ui.saveFailure)throw Error('已开启保存失败演示，关闭后可重试。');const raw=localStorage.getItem(KEY);if(raw&&JSON.parse(raw).revision!==S.revision)throw Error('另一窗口已更新数据，请先核对最新版本再重试。当前输入已保留。');fn();S.revision++;S.audit.unshift({id:'AU-'+Date.now()+'-'+S.revision,action,subject,actor:who().name,role:who().role,reason:reason||'用户主动操作',time:now(),result:'演示成功'});localStorage.setItem(KEY,JSON.stringify(S));storageFailed=false;undo={state:before,revision:S.revision,action};ui.dirty=false;notify(action+'已保存 · 仅本机演示');render();return true;}catch(e){S=before;storageFailed=true;notify('操作未保存：'+e.message);const err=$('#form-error')||$('#modal-error');if(err)err.textContent='操作未保存：'+e.message;return false;}}
function requireScope(scope){if(!allowed(scope)){notify('当前身份无操作权限，请切换授权身份。');return false;}return true;}
const btn=(text,action,id='',kind='')=>`<button type="button" class="button ${kind}" data-action="${action}" data-id="${esc(id)}">${text}</button>`;
const link=(text,r,id='',kind='')=>`<a class="button ${kind}" href="#/${r}${id?'/'+encodeURIComponent(id):''}" data-nav="${r}" data-id="${esc(id)}">${text}</a>`;
const badge=s=>`<span class="badge ${/强停|驳回|限制|撤回|失败|异常/.test(s)?'bad':/待|草稿|冷静|退回/.test(s)?'warn':''}">${esc(s)}</span>`;
const panel=(title,body,extra='')=>`<section class="panel"><div class="actions" style="justify-content:space-between;margin-bottom:14px"><h2 style="margin:0">${title}</h2>${extra}</div>${body}</section>`;
const field=(label,key,value='',type='text',hint='')=>`<label class="field"><span>${label}</span>${type==='textarea'?`<textarea name="${key}" required>${esc(value)}</textarea>`:`<input name="${key}" type="${type}" value="${esc(value)}" required>`}${hint?`<small>${hint}</small>`:''}</label>`;
const select=(label,key,options,value)=>`<label class="field"><span>${label}</span><select name="${key}">${options.map(x=>`<option value="${esc(x[0])}" ${value===x[0]?'selected':''}>${esc(x[1])}</option>`).join('')}</select></label>`;
const rows=pairs=>pairs.map(([k,v])=>`<div class="detail-row"><span>${k}</span><span>${v}</span></div>`).join('');
const events=items=>`<div class="timeline">${items.length?items.slice().reverse().map(x=>`<div class="event">${esc(x.text||x.reason||x.action)}<small>${esc(x.actor||'系统样例')} · ${esc(x.time||now())}</small></div>`).join(''):'<p class="muted">暂无流转记录，后续操作将在这里留痕。</p>'}</div>`;
function get(collection,fallback){return S[collection].find(x=>x.id===currentId)||S[collection][fallback||0];}
function list(collection,columns,row,options=[]){const all=S[collection],q=ui.q.toLowerCase(),found=all.filter(x=>JSON.stringify(x).toLowerCase().includes(q)&&(ui.filter==='全部'||[x.status,x.stage,x.category,x.type].includes(ui.filter)));const size=ui.mode==='full'?20:6,max=Math.max(1,Math.ceil(found.length/size));ui.page=Math.min(ui.page,max);let chunk=found.slice((ui.page-1)*size,ui.page*size);return `<div class="toolbar"><input id="list-search" aria-label="搜索${routes[route()][0]}" placeholder="搜索名称、编号或关键词" value="${esc(ui.q)}"><select id="list-filter" aria-label="筛选状态"><option>全部</option>${options.map(x=>`<option ${ui.filter===x?'selected':''}>${esc(x)}</option>`).join('')}</select><span class="count">共 ${found.length} 条 · 拟真样例</span>${btn('导出筛选结果','export',collection,'small')}</div><section class="panel no-pad"><div class="table-wrap"><table><thead><tr>${columns.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${chunk.map(row).join('')||`<tr><td colspan="${columns.length}"><div class="empty"><strong>没有匹配结果</strong><span class="muted">换个关键词或清除筛选再试。</span>${btn('清除筛选','clear')}</div></td></tr>`}</tbody></table></div><div class="pagination"><span>第 ${ui.page} / ${max} 页 · 每页 ${size} 条</span><div class="actions">${btn('上一页','prev','','small')}${btn('下一页','next','','small')}</div></div></section>`;}
function openModal(title,body,action,id){modalAction=action;modalSubject=id;const m=$('#modal');m.innerHTML=`<form id="modal-form"><div class="modal-body"><h2 id="modal-title">${title}</h2>${body}<div class="form-error" id="modal-error" role="alert"></div></div><div class="modal-footer">${btn('取消','cancel') }<button class="button primary" type="submit">确认并保存</button></div></form>`;m.showModal();}
const reasonForm=(hint='请说明依据、影响与处理原因')=>field('操作原因','reason','','textarea',hint);
function statePanel(){const mode=ui.mode;if(mode==='loading')return `<section class="panel state-loading" aria-busy="true" aria-busy="true"><p>正在载入${routes[route()][0]}样例…</p><div class="skeleton"></div><div class="skeleton big"></div><div class="skeleton"></div>${btn('完成加载','normal')}</section>`;if(mode==='empty')return `<section class="panel empty"><div class="empty-icon state-ill state-empty" aria-hidden="true"><svg viewBox="0 0 120 96" fill="none" stroke-linecap="round" stroke-linejoin="round"><rect x="18" y="30" width="84" height="54" rx="10" class="f-soft"/><path d="M18 52h24l6 10h24l6-10h24" class="s-brand" stroke-width="3"/><path d="M40 20l6 8M60 14v12M80 20l-6 8" class="s-mut" stroke-width="3"/></svg></div><h2>${routes[route()][0]}暂无记录</h2><p class="muted">当前演示选择了空数据状态。已保存的数据没有删除。</p><div class="actions">${btn('载入拟真样例','normal','', 'primary')}${route()==='content'?link('新建内容','editor'):route()==='media'?link('上传资源','upload'):link('返回工作台','dash')}</div></section>`;if(mode==='error')return `<section class="panel empty"><div class="empty-icon state-ill state-error" aria-hidden="true"><svg viewBox="0 0 120 96" fill="none" stroke-linecap="round" stroke-linejoin="round"><circle cx="60" cy="50" r="34" class="f-bad"/><path d="M60 32v22" class="s-bad" stroke-width="6"/><circle cx="60" cy="66" r="4" class="d-bad"/><path d="M98 22l8-6M104 34h8M16 28l-8-4" class="s-mut" stroke-width="3"/></svg></div><h2>这次没有载入成功</h2><p class="muted">演示读取失败，不代表业务数据为空。你的输入与原记录已保留。</p>${btn('重试读取','normal','','primary')}</section>`;if(mode==='permission'||!allowed(routes[route()][2]))return `<section class="panel empty"><div class="empty-icon state-ill state-permission" aria-hidden="true"><svg viewBox="0 0 120 96" fill="none" stroke-linecap="round" stroke-linejoin="round"><rect x="34" y="42" width="52" height="40" rx="9" class="f-soft"/><path d="M44 42V32a16 16 0 0 1 32 0v10" class="s-brand" stroke-width="5"/><circle cx="60" cy="60" r="5" class="d-brand"/><path d="M60 65v7" class="s-brand" stroke-width="4"/></svg></div><h2>此操作需要授权身份</h2><p class="muted">${esc(who().name)} · ${esc(who().role)}无法访问${routes[route()][0]}。角色拒绝不会伪装为空数据。</p><div class="actions">${link('切换演示身份','identity','','primary')}${btn('退出无权限演示态','normal')}</div></section>`;return null;}
const navGroups=[['工作空间',[['dash','◫','运营工作台']]],['内容管理',[['content','▤','内容资产'],['review','✓','双人审核'],['publish','⇧','发布管理'],['media','▧','媒体资源']]],['学员与服务',[['students','◉','学员管理'],['tickets','▣','客服工单'],['privacy','⌁','隐私请求']]],['商业与治理',[['orders','▦','商城订单'],['refunds','↶','退款审批'],['reconcile','⇄','对账与权益'],['governance','◇','风险案件'],['reports','⚑','举报核查']]],['平台管理',[['audit','≡','审计日志'],['observability','⌇','运行观测'],['recovery','⟳','恢复任务'],['permissions','⊞','权限矩阵'],['identity','⚙','身份与设置']]]];
function renderBody(r){const collections={editor:'content',contentdetail:'content',reviewdetail:'content',versions:'content',riskdetail:'risks',reportdetail:'reports',studentdetail:'students',studentaction:'students',ticketdetail:'tickets',orderdetail:'orders',refunddetail:'refunds',privacydetail:'privacy',auditdetail:'audit'};if(currentId&&collections[r]&&!S[collections[r]].some(x=>x.id===currentId))return '<section class="panel empty"><h2>没有找到这条记录</h2><p class="muted">目标可能已重置或不存在，没有替你打开另一条记录。</p>'+link('返回工作台','dash','','primary')+'</section>';return views[r]();}
function render(){const draft=ui.dirty?Array.from(document.querySelectorAll('main form input,main form textarea,main form select')).map(x=>({name:x.name,value:x.value,checked:x.checked,type:x.type})):[];let r=route();document.documentElement.dataset.theme=S.theme;if(!S.authenticated&&r!=='login'){location.hash='#/login';r='login';}const title=routes[r];$('#app').innerHTML=r==='login'?login():`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-icon">语</span><div>语学星<small>OPERATIONS WORKSPACE</small></div></div><nav aria-label="管理主导航">${navGroups.filter(([,items])=>items.some(([routeName])=>allowed(routes[routeName][2]))).map(([g,items])=>`<div class="nav-group">${g}</div>${items.filter(([routeName])=>allowed(routes[routeName][2])).map(([routeName,icon,t])=>`<a href="#/${routeName}" data-nav="${routeName}" class="${r===routeName?'active':''}"><span aria-hidden="true">${icon}</span>${t}</a>`).join('')}`).join('')}</nav><div class="side-foot">产品演示环境 · V2<br>职责分离 / 本机留痕 / 无真实请求</div></aside><div class="workspace"><header class="topbar"><span class="crumb">运营中心 / ${title[0]}</span>${btn(S.theme==='light'?'☾ 深色':'☼ 浅色','theme','','small')}<span class="avatar">${who().name[0]}</span><span class="identity">${esc(who().name)}<small>${esc(who().role)}</small></span>${link('切换身份','identity','','small')}</header>${storageFailed||parseFailed?`<div class="storage-warning" role="alert">${parseFailed?'旧缓存版本不匹配，尚未覆盖原缓存。':'本机保存失败或另一窗口已有更新。未保存的表单输入仍保留，业务动作未完成。'}${btn('读取最新数据','refresh-storage','','small')}</div>`:''}<main id="main" tabindex="-1"><div class="heading"><div><div class="eyebrow">${title[1]}</div><h1>${title[0]}</h1><p class="sub">${descriptions[r]||'以版本、操作依据与审计记录连接每一个业务动作。'}</p></div><label class="states">演示状态<select id="state-mode" aria-label="页面演示状态">${[['normal','正常态'],['loading','加载态'],['empty','空态'],['full','满数据态'],['error','错误态'],['permission','无权限态']].map(([v,t])=>`<option value="${v}" ${ui.mode===v?'selected':''}>${t}</option>`).join('')}</select></label></div>${ui.mode==='full'?'<div class="callout">满数据演示：列表每页展示 20 条，保留筛选、分页和完整操作。</div>':''}${statePanel()||renderBody(r)}</main></div></div>`;for(const d of draft){const el=document.querySelector('main form [name="'+d.name+'"]');if(el){if(d.type==='checkbox')el.checked=d.checked;else el.value=d.value;}}}
const descriptions={dash:'把待办、风险与恢复任务放在同一张工作台，先处理需要你确认的事项。',content:'从草稿到正式发布，每次内容修改都建立新版本，审核记录随版本保存。',review:'作者、初审、终审与发布者职责分离。退回须说明原因，修改后重新双审。',publish:'只发布版权、媒体与双审均合格的版本，强制下架不允许普通回滚复活。',tickets:'接单、补充信息、升级与接收分开记录；处理结果明确后才关闭。',refunds:'两名财务分别审批，申请人不可审批；审批完成也不等于渠道到账。',privacy:'导出、撤回同意与账号删除是不同流程，账号删除保留 168 小时冷静期。',observability:'指标来自静态样例与本机动作，仅用于体验运营处置流程。',identity:'选择不同职责的演示账号，验证菜单、页面与业务动作的权限边界。'};
function login(){return `<main id="main" class="login"><section class="hero"><div class="tagline">YUXUEXING / OPERATIONS</div><h1>把每一次运营决策<br>放在清晰的事实之上。</h1><p class="muted">内容质量、学员服务与业务运行，一站协同。<br>这是本地拟真工作台，不连接正式认证服务。</p><div class="actions">${badge('内容双审')}${badge('职责分离')}${badge('全程留痕')}</div></section><section class="panel"><h2>登录演示工作台</h2><p class="sub">选择身份，使用任意 8 位以上演示密码。密码不保存。</p><form id="login-form">${select('演示身份','identity',identities.map(x=>[x.id,x.name+' · '+x.role]),S.identity)}${field('演示密码','password','','password','请勿输入任何真实密码。')}<div id="form-error" class="form-error" role="alert"></div><button type="submit" class="button primary" style="width:100%">进入工作台 →</button></form><p class="muted" style="font-size:11px;margin-top:18px">当前状态：${esc(ui.mode)} · 登录不创建真实账户。</p><label class="states">状态演示<select id="state-mode">${[['normal','正常'],['loading','加载'],['empty','空态'],['full','满数据'],['error','错误'],['permission','无权限']].map(([v,t])=>`<option value="${v}" ${v===ui.mode?'selected':''}>${t}</option>`).join('')}</select></label>${ui.mode==='normal'||ui.mode==='full'?'':`<div class="callout ${ui.mode==='error'?'bad':'warn'}">${({loading:'身份样例正在加载，点击下方按钮完成。',empty:'未载入身份列表，可重新加载样例。',error:'演示登录服务异常，未保存任何密码。',permission:'演示账号无权限，选择授权身份再试。'})[ui.mode]} ${btn('恢复登录','normal','','small')}</div>`}</section></main>`;}
const views={};
views.dash=()=>`<div class="metrics">${[['待审核版本',S.content.filter(x=>/待.*审/.test(x.status)).length,'独立审核，避免重复修改'],['待响应工单',S.tickets.filter(x=>x.status==='待接单').length,'接单后保存责任人与时间'],['运行中学员',S.students.filter(x=>x.stage==='学习中').length,'仅当前演示样例'],['待恢复任务',S.jobs.reduce((n,x)=>n+x.pending,0),'先核对事实，再执行恢复']].map(([t,n,d])=>`<section class="metric"><span class="muted">${t}</span><div class="number">${n}</div><small>${d}</small></section>`).join('')}</div><div class="grid"><div>${panel('今天需要关注',S.tickets.slice(0,4).map(x=>`<div class="detail-row"><div><strong>${esc(x.title)}</strong><p class="sub">${x.id} · ${x.category}</p></div><div class="actions">${badge(x.status)}${allowed('tickets')?link('查看','ticketdetail',x.id,'small'):badge('客服处理')}</div></div>`).join(''))}${panel('近七日服务趋势',`<p class="muted">合成数据 · 工单新增量</p><div class="chart">${[38,58,48,84,65,94,52].map((n,i)=>`<div class="bar" style="height:${n}%" aria-label="周${i+1} ${Math.round(n/4)}条"><span>周${i+1}</span></div>`).join('')}</div>`)}</div><div>${panel('团队协作',`<p class="muted">当前身份：${who().role}。按职责切换身份，完成全链演示。</p>${link('查看身份与权限','identity','','primary')}`)}${panel('最近操作',events(S.audit.slice(0,5).map(x=>({text:x.action+' · '+x.subject,actor:x.actor,time:x.time}))))}</div></div>`;
views.content=()=>`<div class="actions" style="margin-bottom:18px">${link('＋ 新建内容','editor','','primary')}${link('审核队列','review')}${link('发布管理','publish')}</div>`+list('content',['内容 / 编号','类型 / 等级','版本','状态','更新时间','操作'],x=>`<tr><td><strong>${esc(x.title)}</strong><small>${x.id}</small></td><td>${x.type} / ${x.level}</td><td>v${x.version}</td><td>${badge(x.status)}</td><td>${x.updated}</td><td><div class="actions">${link('详情','contentdetail',x.id,'small')}${link('编辑','editor',x.id,'small')}</div></td></tr>`,['草稿','待初审','待终审','可发布','已发布','已下架','强制下架']);
views.editor=()=>{const c=currentId?get('content'):null;return `<div class="grid"><section class="panel"><h2>${c?'编辑 · '+esc(c.id):'创建学习内容'}</h2><form id="content-form" data-id="${c?.id||''}">${field('内容标题','title',c?.title||'') }<div class="grid equal">${select('内容类型','type',['阅读','词汇','语法','听力','口语','写作'].map(x=>[x,x]),c?.type||'阅读')}${select('学习等级','level',['A1','A2','B1','B2','C1'].map(x=>[x,x]),c?.level||'B1')}</div>${field('正文 / 题目材料','text',c?.text||'','textarea','至少 20 个字符，演示内容不能包含真实用户信息。')}<label class="check"><input type="checkbox" name="rights" ${c?.rights?'checked':''}>版权与授权来源已核验</label><label class="check"><input type="checkbox" name="media" ${c?.media?'checked':''}>必要媒体已绑定且可用</label><div id="form-error" class="form-error" role="alert"></div><div class="actions"><button type="submit" class="button primary">保存新工作版本</button>${link('取消编辑','content')}</div></form></section><div>${panel('版本规则',`<div class="callout">保存修改会建立新草稿版本，旧审核意见保留但签核不继承。</div>${rows([['编辑主体',esc(who().name)],['当前版本',c?'v'+c.version:'待创建'],['已发布指针',c?.published?'v'+c.published:'无']])}`)}${panel('发布前检查',`<p>1. 原创或获得明确授权</p><p>2. 正文、题目与必要媒体一致</p><p>3. L1 / L2 由不同人员审核</p><p>4. 独立发布者确认可分发版本</p>`)}</div></div>`;};
views.contentdetail=()=>{const c=get('content');return `<div class="actions" style="margin-bottom:18px">${link('返回列表','content')}${link('编辑新版本','editor',c.id)}${c.status==='草稿'&&who().id===c.author?btn('补齐材料并送审','submit-content',c.id,'primary'):''}${link('版本与回滚','versions',c.id)}</div><div class="grid">${panel(esc(c.title),`<p class="actions">${badge(c.status)}${badge(c.type)}${badge(c.level)}${badge('v'+c.version)}</p><p style="white-space:pre-wrap">${esc(c.text)}</p>${rows([['作者',name(c.author)],['版权',c.rights?'已核验':'未核验'],['必要媒体',c.media?'已就绪':'未就绪'],['初审',c.l1?name(c.l1):'待审核'],['终审',c.l2?name(c.l2):'待审核']])}`)}${panel('审核与版本历史',events(c.notes))}</div>`;};
views.review=()=>list('content',['审核对象','版本','作者','当前阶段','操作'],c=>`<tr><td><strong>${esc(c.title)}</strong><small>${c.id}</small></td><td>v${c.version}</td><td>${name(c.author)}</td><td>${badge(c.status)}</td><td>${link('核查并决定','reviewdetail',c.id,'small')}</td></tr>`,['待初审','待终审','可发布','草稿']);
views.reviewdetail=()=>{const c=get('content');return `<div class="callout">${who().id==='l1'?'当前为初审主体，终审必须换另一人。':who().id==='l2'?'当前为终审主体，必须有同版本初审批准。':'当前身份只能阅读，不可提交审核决定。'} 作者、L1、L2 与发布者不能由同一人代替。</div><div class="grid"><div>${panel('材料核验 · '+esc(c.title),`<p>${esc(c.text)}</p>${rows([['版本 / 状态','v'+c.version+' / '+c.status],['版权',c.rights?'已确认':'缺失'],['媒体',c.media?'可用':'缺失'],['作者',name(c.author)],['L1 签核',c.l1?name(c.l1):'未批准'],['L2 签核',c.l2?name(c.l2):'未批准']])}`)}${panel('历史意见',events(c.notes))}</div><section class="panel"><h2>提交审核决定</h2><form id="review-form" data-id="${c.id}">${select('审核决定','decision',[['approve','通过'],['changes','要求修改'],['reject','驳回']],'approve')}${field('审核依据与意见','reason','','textarea','退回或驳回必须明确说明修改项，不沿用旧签核。')}<div id="form-error" class="form-error" role="alert"></div><button type="submit" class="button primary">确认审核决定</button></form></section></div>`;};
views.publish=()=>list('content',['内容版本','双签记录','发布指针','当前状态','操作'],c=>`<tr><td><strong>${esc(c.title)}</strong><small>${c.id} / v${c.version}</small></td><td>${name(c.l1)} / ${name(c.l2)}</td><td>${c.published?'v'+c.published:'未发布'}</td><td>${badge(c.status)}${c.published?badge('目录：'+release(c)):''}</td><td><div class="actions">${c.status==='可发布'?btn('发布','publish',c.id,'small primary'):''}${release(c)==='已下架'?btn('恢复同版上架','restore-publish',c.id,'small'):''}${c.published&&release(c)==='已发布'?btn('下架','unpublish',c.id,'small')+btn('强制下架','force',c.id,'small danger'):''}${link('版本','versions',c.id,'small')}</div></td></tr>`,['可发布','已发布','已下架','强制下架']);
views.versions=()=>{const c=get('content');return `<div class="callout">当前发布指针 ${c.published?'v'+c.published:'无'}。回滚只选择已有合格发布快照，强停版本禁止复活。</div>${panel(esc(c.title)+' · 历史快照',`<div class="table-wrap"><table><thead><tr><th>版本</th><th>标题</th><th>发布日期</th><th>资格</th><th>动作</th></tr></thead><tbody>${c.history.map(h=>`<tr><td>v${h.v}</td><td>${esc(h.title)}</td><td>${h.date}</td><td>${badge(c.blocked.includes(h.v)?'强制禁供':h.rights&&h.media?'合格':'失效')}</td><td>${h.v!==c.published&&!c.blocked.includes(h.v)?btn('回滚至此版本','rollback',c.id+':'+h.v,'small'):badge(h.v===c.published?'当前版本':'不可恢复')}</td></tr>`).join('')||'<tr><td colspan="5">暂无历史发布快照，请完成审核并首次发布。</td></tr>'}</tbody></table></div>`)}${panel('处置与同步记录',events(c.notes))}`;};
views.media=()=>`<div class="actions" style="margin-bottom:18px">${link('＋ 上传资源','upload','','primary')}</div>`+list('media',['资源','类型','大小','绑定内容','状态','操作'],m=>`<tr><td><strong>${esc(m.name)}</strong><small>${m.id}</small></td><td>${m.kind}</td><td>${m.size}</td><td>${m.content}</td><td>${badge(m.status)}</td><td>${btn(m.status==='隔离'?'恢复资源':'隔离资源','media-toggle',m.id,'small')}</td></tr>`,['可用','隔离']);
views.upload=()=>`<div class="grid"><section class="panel"><h2>选择文件并绑定内容</h2><form id="upload-form"><label class="field"><span>本地文件（不上传任何服务器）</span><input type="file" name="file" accept="image/*,audio/*,video/*" required><small>仅保存文件名、类型与大小，不保存文件字节；最大 20 MB。</small></label>${select('绑定内容','content',S.content.map(c=>[c.id,c.title]),S.content[0].id)}<label class="check"><input type="checkbox" name="rights" required>我确认这是可用于本机演示的原创或授权素材</label><div id="form-error" class="form-error" role="alert"></div><button class="button primary" type="submit">验证文件并保存记录</button></form></section>${panel('媒体合格条件',`<p>格式、大小、版权与绑定版本分别验证。</p><p class="muted">静态演示不会产生真实转码、安全扫描或上传回执。</p>`)}</div>`;
views.students=()=>list('students',['学员 / 编号','学习阶段','等级','学习天数','正确率','操作'],s=>`<tr><td><strong>${esc(s.name)}</strong><small>${s.id}</small></td><td>${badge(s.restricted?'账号受限':s.stage)}</td><td>${s.level}</td><td>${s.days} 天</td><td>${s.accuracy}%</td><td>${link('查看档案','studentdetail',s.id,'small')}</td></tr>`,['学习中','新注册','错题待补救','同意已撤回']);
views.studentdetail=()=>{const s=get('students');return `<div class="actions" style="margin-bottom:18px">${link('返回学员列表','students')}${link('处理学员请求','studentaction',s.id,'primary')}</div><div class="grid">${panel(esc(s.name)+' · 学习档案',`${rows([['样例身份',s.id],['加入日期',s.joined],['当前等级',s.level],['学习天数',s.days+' 天'],['练习正确率',s.accuracy+'%'],['基础同意',s.consent?'已同意':'已撤回'],['访问状态',s.restricted?'运营限制':s.consent?'通过学习门':'学习能力受限']])}<div class="callout">运营不能代学员补签同意，不能直接修改学习成绩或订单事实。</div>`)}<div>${panel('学习状态',`<p>${badge(s.stage)}</p><div class="chart">${[42,65,77,56,82,90,71].map((v,i)=>`<div class="bar" style="height:${v}%"><span>${i+1}日</span></div>`).join('')}</div>`)}${panel('处理记录',events(s.notes))}</div></div>`;};
views.studentaction=()=>{const s=get('students');return `<div class="grid"><section class="panel"><h2>${esc(s.name)} · 受控处理</h2><form id="student-form" data-id="${s.id}">${select('处理类型','action',[['note','记录服务说明'],['restrict','限制账号访问'],['restore','解除运营限制']],'note')}${reasonForm('请输入可核验的处理依据；解除运营限制不会恢复已撤回的学习同意。')}<label class="check"><input name="confirm" type="checkbox" required>已核对身份、工单与处置范围</label><div id="form-error" class="form-error" role="alert"></div><button type="submit" class="button primary">保存处理决定</button></form></section>${panel('当前事实',rows([['账号',s.id],['同意状态',s.consent?'有效':'已撤回'],['运营限制',s.restricted?'已限制':'未限制']])+events(s.notes))}</div>`;};
views.tickets=()=>list('tickets',['工单 / 主题','学员','分类','责任人','状态','操作'],t=>`<tr><td><strong>${esc(t.title)}</strong><small>${t.id}</small></td><td>${t.student}</td><td>${t.category}</td><td>${name(t.assignee)}</td><td>${badge(t.status)}</td><td>${link('进入工单','ticketdetail',t.id,'small')}</td></tr>`,['待接单','处理中','待用户补充','待二线接收','已解决','已关闭']);
views.ticketdetail=()=>{const t=get('tickets');return `<div class="actions" style="margin-bottom:18px">${link('返回队列','tickets')}${badge(t.status)}${t.status==='待接单'?btn('接单','claim-ticket',t.id,'primary'):''}${t.status==='待二线接收'&&t.target===who().id?btn('确认接收','receive-ticket',t.id,'primary'):''}${t.status==='已关闭'?btn('重新打开','reopen-ticket',t.id):''}</div><div class="grid"><div>${panel(esc(t.title),`${rows([['编号',t.id],['学员',t.student],['责任人',name(t.assignee)],['接收人',name(t.target)]])}${t.safe?`<div class="reply"><strong>学员来信 · 拟真正文</strong><p>${esc(t.body)}</p></div>`:`<div class="callout warn">历史 hash-only 工单，缺少安全正文。禁止虚构回复或关闭，可请求补充或指定二线接收。</div>`}${t.messages.map(m=>`<div class="reply"><strong>${esc(m.actor)} · ${esc(m.time)}</strong><p>${esc(m.text)}</p><small class="muted">本机消息，未向学员真实发送</small></div>`).join('')}`)}${t.assignee===who().id&&['处理中','待用户补充'].includes(t.status)?`<section class="panel"><h2>回复与流转</h2><form id="ticket-form" data-id="${t.id}">${field('处理说明 / 回复正文','reply','','textarea','保留可理解的下一步说明，至少 6 个字符。')}${select('下一步','next',[['reply','保存回复，继续处理'],['wait','请求用户补充'],['resolve','确认解决']],'reply')}<div id="form-error" class="form-error" role="alert"></div><div class="actions"><button type="submit" class="button primary">保存回复与状态</button>${btn('升级给二线','escalate-ticket',t.id)}</div></form></section>`:''}${t.status==='已解决'&&t.assignee===who().id?btn('确认关闭工单','close-ticket',t.id,'primary'):''}</div><div>${panel('交接事实',`${rows([['接收状态',t.status==='待二线接收'?'请求已发出 · 尚未接收':'以流转记录为准'],['升级原因',esc(t.reason||'无')]])}`)}${panel('工单时间线',events(t.events))}</div></div>`;};
views.orders=()=>list('orders',['订单 / 商品','学员','金额','资金状态','权益状态','操作'],o=>`<tr><td><strong>${esc(o.sku)}</strong><small>${o.id} · ${o.date}</small></td><td>${o.student}</td><td>¥${o.amount}.00</td><td>${badge(o.status)}</td><td>${badge(o.entitlement)}</td><td>${link('查看订单','orderdetail',o.id,'small')}</td></tr>`,['已支付','退款处理中','已退款','权益待恢复']);
views.orderdetail=()=>{const o=get('orders'),rf=S.refunds.find(x=>x.order===o.id);return `<div class="grid">${panel(o.id+' · '+esc(o.sku),`${rows([['购买学员',o.student],['合成金额','¥'+o.amount+'.00'],['创建日期',o.date],['资金状态',badge(o.status)],['权益状态',badge(o.entitlement)],['退款记录',rf?link(rf.id,'refunddetail',rf.id,'small'):'无']])}<div class="callout">资金与权益分开记录。不会发起真实退款、扣款或权益发放。</div><div class="actions">${!rf&&o.status!=='已退款'?btn('发起退款申请','request-refund',o.id,'primary'):''}${link('查看对账','reconcile')}</div>`)}${panel('操作追溯',events(S.audit.filter(a=>a.subject.includes(o.id)).map(a=>({text:a.action,actor:a.actor,time:a.time}))))}</div>`;};
views.refunds=()=>list('refunds',['退款 / 订单','申请原因','第一审批','第二审批','状态','操作'],r=>`<tr><td><strong>${r.id}</strong><small>${r.order}</small></td><td>${esc(r.reason)}</td><td>${r.approvals[0]?name(r.approvals[0]):'待审批'}</td><td>${r.approvals[1]?name(r.approvals[1]):'待审批'}</td><td>${badge(r.status)}</td><td>${link('审批详情','refunddetail',r.id,'small')}</td></tr>`,['待双人审批','待渠道处理','渠道处理中','已退款','已拒绝']);
views.refunddetail=()=>{const r=get('refunds');return `<div class="grid">${panel(r.id+' · 退款请求',`${rows([['订单',r.order],['申请人',name(r.applicant)],['申请原因',esc(r.reason)],['状态',badge(r.status)],['财务 A',r.approvals[0]?name(r.approvals[0]):'尚未批准'],['财务 B',r.approvals[1]?name(r.approvals[1]):'尚未批准'],['渠道结果',r.channel]])}<div class="callout warn">必须两名独立财务审批，申请人不可自批；待渠道处理与已到账分开。</div><div class="actions">${r.status==='待双人审批'?btn('批准此退款','approve-refund',r.id,'primary')+btn('拒绝并写明原因','reject-refund',r.id,'danger'):''}${r.status==='待渠道处理'?btn('提交演示渠道','submit-refund',r.id,'primary'):''}${r.status==='渠道处理中'?btn('模拟收到退款成功回执','finish-refund',r.id,'primary'):''}${r.status==='已退款'?btn(r.invoice?'已申请退款凭证':'申请退款凭证','invoice',r.id):''}</div>`)}${panel('资金流转审计',events(S.audit.filter(a=>a.subject.includes(r.id)).map(a=>({text:a.action+' · '+a.reason,actor:a.actor,time:a.time}))))}</div>`;};
views.reconcile=()=>`${panel('差异总览',`<div class="metrics" style="margin:0">${[['待确认资金',S.orders.filter(x=>x.status==='退款处理中').length],['已付待权益',S.orders.filter(x=>x.entitlement==='待开通').length],['退款待渠道',S.refunds.filter(x=>/渠道/.test(x.status)).length],['重复通知',0]].map(([t,n])=>`<div class="metric"><span>${t}</span><div class="number">${n}</div></div>`).join('')}</div>`)}${list('orders',['订单','资金','权益','核对结论','动作'],o=>`<tr><td>${o.id}</td><td>${o.status}</td><td>${o.entitlement}</td><td>${badge(o.entitlement==='待开通'?'需要领域恢复':'事实一致')}</td><td>${o.entitlement==='待开通'?btn('创建恢复任务','create-recovery',o.id,'small'):link('追溯','orderdetail',o.id,'small')}</td></tr>`)}`;
views.governance=()=>list('risks',['案件 / 来源','当前状态','责任人','处置原因','操作'],r=>`<tr><td><strong>${esc(r.title)}</strong><small>${r.id} · ${r.source}</small></td><td>${badge(r.status)}</td><td>${name(r.assignee)}</td><td>${esc(r.reason||'待填写')}</td><td>${link('分诊处置','riskdetail',r.id,'small')}</td></tr>`,['待分诊','处理中','已隔离','已恢复','已结案']);
views.riskdetail=()=>{const r=get('risks');return `<div class="grid"><section class="panel"><h2>${esc(r.title)}</h2>${rows([['案件编号',r.id],['来源',esc(r.source)],['状态',badge(r.status)],['责任人',name(r.assignee)]])}<form id="risk-form" data-id="${r.id}" style="margin-top:18px">${select('处置动作','action',[['assign','受理并分派'],['isolate','隔离演示对象'],['restore','恢复演示对象'],['close','结案']],'assign')}${select('责任人','assignee',identities.filter(i=>i.scopes.includes('governance')).map(i=>[i.id,i.name]),r.assignee||'ops')}${reasonForm('请记录证据、处置范围和影响；这里不修改正式账号或内容。')}<div id="form-error" class="form-error" role="alert"></div><button type="submit" class="button primary">确认处置</button></form></section>${panel('证据与处置时间线',`<div class="callout">样例范围：${esc(r.source)}。保留来源链与处置原因，恢复不删除原隔离记录。</div>${events(r.events)}`)}</div>`;};
views.reports=()=>list('reports',['举报编号','事项','来源','状态','关联案件','操作'],r=>`<tr><td>${r.id}</td><td>${esc(r.subject)}</td><td>${esc(r.source)}</td><td>${badge(r.status)}</td><td>${r.risk||'待建档'}</td><td>${link('核查详情','reportdetail',r.id,'small')}</td></tr>`,['待核实','已建档','已核查']);
views.reportdetail=()=>{const r=get('reports');return `<div class="grid">${panel(r.id+' · '+esc(r.subject),`<p>${esc(r.detail)}</p>${rows([['来源',esc(r.source)],['状态',badge(r.status)],['关联案件',r.risk?link(r.risk,'riskdetail',r.risk,'small'):'未建档']])}<div class="actions" style="margin-top:18px">${!r.risk?btn('核验后建立案件','create-risk',r.id,'primary'):link('查看风险案件','riskdetail',r.risk)}${btn('记录核查结论','check-report',r.id)}</div>`)}${panel('安全预览',`<p>此处是合成证据，不展示举报人真实联系方式。</p><p class="muted">受理不等于违规成立，结论须结合证据并保存理由。</p>`)}</div>`;};
views.privacy=()=>list('privacy',['请求','学员','类型','当前状态','冷静期 / 期限','操作'],p=>`<tr><td>${p.id}</td><td>${p.student}</td><td>${p.type}</td><td>${badge(p.status)}</td><td>${p.due}</td><td>${link('查看流程','privacydetail',p.id,'small')}</td></tr>`,['待核验','冷静期','导出准备中','导出可领取','已撤回','已完成']);
views.privacydetail=()=>{const p=get('privacy');return `<div class="grid">${panel(p.id+' · '+p.type,`${rows([['申请学员',p.student],['请求时间',p.requested],['状态',badge(p.status)],['冷静期结束 / 有效期',p.due],['数据 owner',p.type==='账号删除'?'IAM + 各领域受控命令':'Learner privacy']])}<div class="callout warn">账号删除不是撤回同意。冷静期内可撤回，客服不能跳过期限直接删除；导出领取有有效期。</div><div class="actions">${p.type==='数据导出'&&p.status==='待核验'?btn('确认身份并开始导出','privacy-export',p.id,'primary'):''}${p.status==='导出准备中'?btn('生成本机导出预览','privacy-ready',p.id,'primary'):''}${p.status==='导出可领取'?btn('下载合成数据','privacy-download',p.id,'primary'):''}${p.type==='账号删除'&&p.status==='冷静期'?btn('记录本人撤回申请','privacy-cancel',p.id)+btn('核验冷静期与执行条件','privacy-check',p.id):''}${p.status==='待执行'?btn('执行演示删除','privacy-delete',p.id,'danger'):''}</div>`)}${panel('生命周期记录',events(p.events))}</div>`;};
views.audit=()=>list('audit',['时间 / 回执','操作','主体 / 身份','目标','结果','操作'],a=>`<tr><td>${a.time}<br><small>${a.id}</small></td><td>${esc(a.action)}</td><td>${esc(a.actor)}<br><small>${esc(a.role)}</small></td><td>${esc(a.subject)}</td><td>${badge(a.result)}</td><td>${link('追溯','auditdetail',a.id,'small')}</td></tr>`,['演示成功']);
views.auditdetail=()=>{const a=get('audit');return panel('操作回执 · '+esc(a.id),`${rows([['操作',esc(a.action)],['目标与版本',esc(a.subject)],['实际主体',esc(a.actor)],['职责',esc(a.role)],['依据',esc(a.reason)],['时间',esc(a.time)],['结果',badge(a.result)],['环境','本机静态演示 · 无服务端事实']])}<div class="actions" style="margin-top:20px">${link('返回审计日志','audit')}${btn('导出本条回执','export-one',a.id)}</div>`);};
views.observability=()=>`<div class="metrics">${[['可见样例服务',3],['待恢复消息',S.jobs.reduce((n,j)=>n+j.pending,0)],['公开请求模拟成功率','99.8%'],['P95 样例延迟','128ms']].map(([t,n])=>`<div class="metric"><span class="muted">${t}</span><div class="number">${n}</div><small>合成运行数据，无真实探测</small></div>`).join('')}</div>${panel('服务健康与积压',`<table><thead><tr><th>服务 / 任务</th><th>状态</th><th>积压</th><th>上次样例</th><th>处置</th></tr></thead><tbody>${S.jobs.map(j=>`<tr><td>${j.service}</td><td>${badge(j.status)}</td><td>${j.pending}</td><td>${j.last}</td><td>${link('恢复工作台','recovery',j.id,'small')}</td></tr>`).join('')}</tbody></table>`)}${panel('响应时间分布',`<div class="chart">${[62,75,57,88,66,42,69,54,80,73].map((n,i)=>`<div class="bar" style="height:${n}%"><span>${9+i}:00</span></div>`).join('')}</div><p class="muted">样例曲线，不能用于判断正式发布门通过。</p>`)}`;
views.recovery=()=>`${panel('人工恢复与任务重放',`<div class="callout">仅重放当轮静态任务。需先确认事实、责任 owner 与恢复原因，审计留痕；不会操作真实消息总线。</div><table><thead><tr><th>任务</th><th>领域 / 服务</th><th>状态</th><th>积压</th><th>动作</th></tr></thead><tbody>${S.jobs.map(j=>`<tr><td>${j.id}</td><td>${j.service}</td><td>${badge(j.status)}</td><td>${j.pending}</td><td>${btn(j.pending?'核验并重放':'演示注入失败','replay-job',j.id,'small') }</td></tr>`).join('')}</tbody></table>`)}${panel('恢复审计',events(S.audit.filter(a=>/恢复|重放/.test(a.action)).map(a=>({text:a.action+' · '+a.reason,actor:a.actor,time:a.time}))))}`;
views.permissions=()=>panel('职责与能力矩阵',`<div class="callout">矩阵来自统一演示身份数据。正式权限仍需 IAM 与领域服务核验，本机角色不是安全边界。</div><div class="table-wrap"><table><thead><tr><th>身份</th>${['content','review','publish','students','tickets','refunds','governance','privacy','audit'].map(s=>`<th>${({content:'内容',review:'双审',publish:'发布',students:'学员',tickets:'客服',refunds:'退款',governance:'治理',privacy:'隐私',audit:'审计'})[s]}</th>`).join('')}</tr></thead><tbody>${identities.map(i=>`<tr><td><strong>${i.name}</strong><small>${i.role}</small></td>${['content','review','publish','students','tickets','refunds','governance','privacy','audit'].map(s=>`<td>${i.scopes.includes(s)?'<span aria-label="有权限">✓</span>':'<span aria-label="无权限">—</span>'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${link('切换演示身份','identity','','primary')}`);
views.identity=()=>`<div class="grid"><div>${panel('切换职责身份',`<div class="identity-cards">${identities.map(i=>`<button class="identity-card ${i.id===S.identity?'selected':''}" data-action="switch-identity" data-id="${i.id}"><strong>${i.name} ${i.id===S.identity?'✓':''}</strong><small>${i.role}</small></button>`).join('')}</div>`)}${panel('偏好与会话',`<div class="actions">${btn(S.theme==='light'?'切换到深色':'切换到浅色','theme')}${btn('退出演示账号','logout','','danger')}</div>`)}</div><div>${panel('本机数据管理',`<p class="muted">当前数据修订 r${S.revision}。演示数据与学员端分开保存，不污染真实业务。</p><div class="actions">${btn('一键重置拟真数据','reset','','danger')}${btn('撤销上一次业务操作','undo')}${btn('模拟保存失败','storage-fail')}</div><p class="sub" style="margin-top:15px">撤销保留审计历史；重置仅清除此管理端演示键。</p>`)}${panel('职责分离建议',`<p>内容链：林知夏编辑 → 王芳初审 → 赵磊终审 → 江蔚发布。</p><p>客服链：陈晨接单 → 指定吴晴并说明原因 → 吴晴确认接收。</p><p>退款链：陈晨申请 → 张三审批 → 刘敏审批 → 渠道模拟回执。</p>`)}</div></div>`;
function fail(msg){const e=$('#form-error')||$('#modal-error');if(e)e.textContent=msg;notify(msg);return false;}
function event(item,text){(item.events||item.notes).push({text,actor:who().name,time:now()});}
function consentAction(a,id){if(!requireScope(routes[route()][2]))return;const c=S.content.find(x=>x.id===id);if(a==='submit-content'){if(!c||c.author!==who().id||c.status!=='草稿')return fail('仅当前作者可以将草稿送审。');if(!c.rights||!c.media)return fail('请先在编辑页核验版权与媒体。');transact('内容送审',id+' / v'+c.version,'材料已核验',()=>{c.status='待初审';event(c,'材料齐全，送 L1 初审');});} }
const confirmActions={'restore-publish':['确认恢复同版上架','只恢复已发布且版权、媒体和签核仍合格的同版，不能解除强制禁供。'],publish:['确认发布','发布后形成独立快照，可见目录指针变更。'],unpublish:['确认普通下架','停止新分发，保留历史发布快照。'],force:['确认强制下架','当前版本进入禁供清单，普通回滚不能复活。'],rollback:['确认回滚','只切换到已有合格历史快照，不删除原发布记录。'],rejectrefund:['拒绝退款','拒绝原因会保存在审计与退款记录中。']};
document.addEventListener('click',e=>{if(e.target.closest('a.skip')){e.preventDefault();$('#main')?.focus();$('#main')?.scrollIntoView({block:'start'});return;}const nav=e.target.closest('[data-nav]');if(nav){e.preventDefault();go(nav.dataset.nav,nav.dataset.id);return;}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id||'';
 if(a==='normal'){ui.mode='normal';render();return;}if(a==='cancel'){$('#modal').close();return;}if(a==='clear'){ui.q='';ui.filter='全部';ui.page=1;render();return;}if(a==='prev'||a==='next'){ui.page=Math.max(1,ui.page+(a==='next'?1:-1));render();return;}
 if(a==='theme'){transact('主题切换','个人偏好','用户主动选择',()=>S.theme=S.theme==='light'?'dark':'light');return;}
 if(a==='switch-identity'){if(ui.dirty&&!confirm('切换身份将离开当前未保存表单，确认继续吗？'))return;transact('切换演示身份',id,'验证职责边界',()=>S.identity=id);return;}
 if(a==='logout'){openModal('退出演示账号','<p>会话结束，业务样例保留。再次登录可以继续原工作。</p>','logout','');return;}
 if(a==='reset'){openModal('重置管理端拟真数据','<p>仅清除管理端演示记录，重建原始样例。学员端数据不受影响。</p>','reset','');return;}
 if(a==='undo'){if(!undo)return notify('没有可撤销的本次会话操作。');if(S.revision!==undo.revision)return notify('数据已变化，禁止撤销覆盖后续操作。');const old=undo;transact('撤销操作',old.action,'用户要求恢复前一状态',()=>{const audit=S.audit;const revision=S.revision;S=clone(old.state);S.audit=audit;S.revision=revision;});undo=null;return;}
 if(a==='storage-fail'){ui.saveFailure=!ui.saveFailure;notify(ui.saveFailure?'保存失败演示已开启：下一次业务操作不会保存':'保存失败演示已关闭');return;}
 if(a==='refresh-storage'){try{const raw=localStorage.getItem(KEY);if(raw){const s=JSON.parse(raw);if(s.version!==3)return notify('缓存不兼容，原数据保持不动。可在设置选择重置。');if(ui.dirty&&!confirm('当前表单有未保存输入，读取最新数据将离开当前输入，是否继续？'))return;S=s;}storageFailed=false;ui.saveFailure=false;render();notify('已读取最新本机数据');}catch(e){notify('仍无法读取：'+e.message);}return;}
 if(a==='export'){const collection=S[id].filter(x=>JSON.stringify(x).toLowerCase().includes(ui.q.toLowerCase())&&(ui.filter==='全部'||[x.status,x.stage,x.category,x.type].includes(ui.filter)));download(id+'-demo.json',collection);return;}
 if(a==='export-one'){download(id+'.json',S.audit.find(x=>x.id===id));return;}
 if(!requireScope(routes[route()][2]))return;
 if(a==='submit-content'){consentAction(a,id);return;}
 if(['publish','unpublish','force','rollback','restore-publish'].includes(a)){if(who().id!=='publisher')return fail('只能由独立发布运营执行。');const info=confirmActions[a];openModal(info[0],`<p>${info[1]}</p>${reasonForm()}`,a,id);return;}
 if(a==='media-toggle'){const m=S.media.find(x=>x.id===id);openModal(m.status==='隔离'?'确认恢复媒体':'确认隔离媒体',reasonForm('记录安全核查依据，隔离后不再用于新版本发布。'),a,id);return;}
 if(a==='claim-ticket'){const t=S.tickets.find(x=>x.id===id);if(t.status!=='待接单')return fail('此工单已被接收，请读取最新状态。');transact('客服接单',id,'开始处理',()=>{t.assignee=who().id;t.status='处理中';event(t,'已接单并开始处理');});return;}
 if(a==='escalate-ticket'){const t=S.tickets.find(x=>x.id===id);if(t.assignee!==who().id||!['处理中','待用户补充'].includes(t.status))return fail('只有当前责任人可升级未完成工单。');openModal('升级工单并指定接收人',select('接收人','target',identities.filter(x=>x.scopes.includes('tickets')&&x.id!==who().id).map(x=>[x.id,x.name+' · '+x.role]),'support')+reasonForm('必须说明为什么升级。提交请求不等于对方已接收。'),a,id);return;}
 if(a==='receive-ticket'){const t=S.tickets.find(x=>x.id===id);if(t.target!==who().id||t.status!=='待二线接收')return fail('只有指定接收人可确认接收。');transact('确认接收升级',id,t.reason,()=>{t.assignee=who().id;t.status='处理中';event(t,'指定二线确认接收');});return;}
 if(a==='close-ticket'){const t=S.tickets.find(x=>x.id===id);if(t.assignee!==who().id||t.status!=='已解决'||!t.safe)return fail('须有安全正文和明确解决记录才可关闭。');openModal('确认关闭工单','<p>确认已有明确处理结果；关闭仍保留消息与交接事实。</p>',a,id);return;}
 if(a==='reopen-ticket'){const t=S.tickets.find(x=>x.id===id);if(t.status!=='已关闭')return;transact('重开工单',id,'问题需要再次处理',()=>{t.status='待接单';t.assignee=null;event(t,'工单重开，等待重新接单');});return;}
 if(a==='request-refund'){openModal('提交退款申请',reasonForm('退款与取消续订不同，申请后由两名独立财务审核。'),a,id);return;}
 if(a==='approve-refund'){const r=S.refunds.find(x=>x.id===id);if(!who().id.startsWith('finance')||r.applicant===who().id||r.approvals.includes(who().id)||r.status!=='待双人审批')return fail('需要尚未审批的独立财务身份，申请人及重复审批者不可批准。');openModal('确认财务审批',reasonForm('请确认订单、退款原因与合成金额。'),a,id);return;}
 if(a==='reject-refund'){openModal('拒绝退款',reasonForm('必须保存拒绝原因。'),a,id);return;}
 if(a==='submit-refund'||a==='finish-refund'){const r=S.refunds.find(x=>x.id===id);if(r.approvals.length!==2)return fail('两名财务批准前不可处理渠道。');if(a==='submit-refund'&&r.status!=='待渠道处理'||a==='finish-refund'&&r.status!=='渠道处理中')return fail('状态已变化，禁止重复提交。');openModal(a==='submit-refund'?'提交演示退款渠道':'确认合成退款回执',`<p>此操作不产生真实资金流。${a==='finish-refund'?'同步本机订单与演示权益状态。':'提交后保持渠道处理中。'}</p>`,a,id);return;}
 if(a==='invoice'){const r=S.refunds.find(x=>x.id===id);if(r.invoice)return notify('已申请凭证，不能重复申请。');transact('申请退款凭证',id,'合成退款完成',()=>r.invoice=true);return;}
 if(a==='create-recovery'){if(S.jobs.some(j=>j.order===id))return notify('已有此订单恢复任务，请在恢复工作台核对。');transact('创建权益恢复任务',id,'已支付但权益未开通',()=>S.jobs.push({id:'JOB-'+Date.now(),service:'订单权益恢复 '+id,status:'待人工复核',pending:1,last:now(),order:id}));return;}
 if(a==='create-risk'||a==='check-report'){openModal(a==='create-risk'?'从举报建立案件':'记录举报核查结论',reasonForm('保留举报来源，不能把受理当作违规成立。'),a,id);return;}
 if(a.startsWith('privacy-')){const p=S.privacy.find(x=>x.id===id);if(a==='privacy-download'){if(p.status!=='导出可领取')return fail('导出未完成，不可领取。');if(new Date(p.due+'T23:59:59')<new Date())return fail('合成导出已过有效期，请重新申请。');download(p.id+'-synthetic.json',{demo:true,student:S.students.find(x=>x.id===p.student),purpose:'仅本机拟真数据导出'});return;}
 if(a==='privacy-check'){if(new Date(p.due+'T00:00:00')>new Date())return notify('168 小时冷静期尚未结束，禁止提前执行删除。');transact('隐私删除条件核验',id,'合成期限已到，进入待执行',()=>{p.status='待执行';event(p,'冷静期结束，等待受控执行');});return;}
 openModal(({ 'privacy-export':'确认身份并准备导出','privacy-ready':'生成合成导出','privacy-cancel':'记录本人撤回删除申请','privacy-delete':'确认删除演示账号'})[a],reasonForm('记录身份核验或本人指令依据；仅影响本机样例。'),a,id);return;}
 if(a==='replay-job'){const j=S.jobs.find(x=>x.id===id);openModal(j.pending?'核验并重放静态任务':'演示注入任务失败',reasonForm('记录领域 owner、核对结论与恢复理由，不直接改跨领域事实。'),a,id);return;}
});
function download(filename,obj){const blob=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('合成数据已导出');}
document.addEventListener('change',e=>{if(e.target.id==='state-mode'){ui.mode=e.target.value;ui.page=1;render();return;}if(e.target.id==='list-filter'){ui.filter=e.target.value;ui.page=1;render();return;}if(e.target.closest('form'))ui.dirty=true;});
document.addEventListener('input',e=>{if(e.target.id==='list-search'){const start=e.target.selectionStart;ui.q=e.target.value;ui.page=1;render();$('#list-search')?.focus();$('#list-search')?.setSelectionRange(start,start);return;}if(e.target.closest('form'))ui.dirty=true;});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,fd=new FormData(form),data=Object.fromEntries(fd.entries()),id=form.dataset.id;const error=$('#form-error')||$('#modal-error');if(error)error.textContent='';
 if(ui.saveFailure)return fail('操作未保存：已开启保存失败演示。关闭失败开关后再提交，当前输入已保留。');
 if(form.id==='login-form'){if(ui.mode!=='normal'&&ui.mode!=='full')return fail('请先恢复正常登录演示态。');if(data.password.length<8)return fail('演示密码至少 8 位，密码不保存。');if(!identities.some(x=>x.id===data.identity))return fail('请选择合法演示身份。');if(transact('演示登录',data.identity,'合成身份选择',()=>{S.identity=data.identity;S.authenticated=true;}))go('dash');return;}
 if(!S.authenticated||!requireScope(routes[route()][2]))return;
 if(form.id==='content-form'){const c=S.content.find(x=>x.id===id);if(who().id!=='editor'||c&&c.author!==who().id)return fail('仅内容作者可编辑工作版本。');if(data.title.trim().length<4)return fail('标题至少 4 个字符。');if(data.text.trim().length<20)return fail('材料至少 20 个字符。');const nid=c?.id||'C-'+Date.now();if(transact('保存内容草稿',nid,'建立新工作版本',()=>{if(c){c.releaseStatus=release(c);c.version++;c.title=data.title.trim();c.text=data.text.trim();c.type=data.type;c.level=data.level;c.rights=!!data.rights;c.media=!!data.media;c.status='草稿';c.l1=null;c.l2=null;c.updated=now();event(c,'保存新版本，原签核失效');}else S.content.push({id:nid,title:data.title.trim(),text:data.text.trim(),type:data.type,level:data.level,version:1,status:'草稿',author:who().id,rights:!!data.rights,media:!!data.media,l1:null,l2:null,history:[],published:null,blocked:[],notes:[],updated:now()});}))go('contentdetail',nid);return;}
 if(form.id==='review-form'){const c=S.content.find(x=>x.id===id),isL1=who().id==='l1',isL2=who().id==='l2';if(!isL1&&!isL2||who().id===c.author||who().id===c.l1)return fail('审核主体必须与作者及上一级不同。');if(isL1&&c.status!=='待初审'||isL2&&(c.status!=='待终审'||!c.l1))return fail('当前版本不处于你的审核阶段。');if(data.reason.trim().length<4)return fail('请填写至少 4 个字的审核依据或整改理由。');if(data.decision==='approve'&&(!c.rights||!c.media))return fail('版权或媒体缺失，不能批准。');transact('内容审核决定',id+' / v'+c.version,data.reason,()=>{event(c,(isL1?'L1':'L2')+' '+({approve:'通过',changes:'要求修改',reject:'驳回'})[data.decision]+'：'+data.reason);if(data.decision==='approve'){c[isL1?'l1':'l2']=who().id;c.status=isL1?'待终审':'可发布';}else{c.version++;c.status='草稿';c.l1=null;c.l2=null;event(c,'新草稿版本 v'+c.version+'，旧签核不继承');}});return;}
 if(form.id==='upload-form'){const file=fd.get('file');if(!file||!file.size)return fail('请选择有效的本地媒体文件。');if(file.size>20*1024*1024)return fail('文件超过 20 MB，请选择更小的素材。');if(!/^(image|audio|video)\//.test(file.type))return fail('仅支持图片、音频或视频。');transact('绑定媒体样例',data.content,'素材来源已确认',()=>{S.media.push({id:'M-'+Date.now(),name:file.name,size:(file.size/1024).toFixed(0)+' KB',kind:file.type.split('/')[0],status:'可用',content:data.content});});return;}
 if(form.id==='student-form'){if(who().id!=='ops')return fail('只有运营负责人可以进行账号限制处理。');if(data.reason.trim().length<6)return fail('处理依据至少 6 个字。');const s=S.students.find(x=>x.id===id);transact('学员受控处理',id,data.reason,()=>{if(data.action==='restrict')s.restricted=true;if(data.action==='restore')s.restricted=false;event(s,({note:'服务说明',restrict:'运营限制',restore:'解除运营限制'})[data.action]+'：'+data.reason);});return;}
 if(form.id==='ticket-form'){const t=S.tickets.find(x=>x.id===id);if(t.assignee!==who().id||!['处理中','待用户补充'].includes(t.status))return fail('工单责任人或状态已变化。');if(data.reply.trim().length<6)return fail('回复至少 6 个字符，不能空白提交。');if(!t.safe&&data.next!=='wait')return fail('缺少安全正文，仅允许请求补充或升级。');transact('客服回复与流转',id,data.reply,()=>{t.messages.push({text:data.reply.trim(),actor:who().name,time:now()});t.status=({reply:'处理中',wait:'待用户补充',resolve:'已解决'})[data.next];event(t,'保存本机回复：'+t.status);});return;}
 if(form.id==='risk-form'){const r=S.risks.find(x=>x.id===id);if(data.reason.trim().length<6)return fail('风险处置依据至少 6 个字。');if(data.action==='restore'&&r.status!=='已隔离')return fail('只有已隔离对象可以执行恢复。');transact('风险案件处置',id,data.reason,()=>{r.assignee=data.assignee;r.reason=data.reason;r.status=({assign:'处理中',isolate:'已隔离',restore:'已恢复',close:'已结案'})[data.action];event(r,r.status+'：'+data.reason);});return;}
 if(form.id==='modal-form')submitModal(data);
});
function submitModal(data){const a=modalAction,id=modalSubject,reason=data.reason?.trim()||'';if($('#modal [name=reason]')&&reason.length<4)return fail('请填写至少 4 个字符的有效原因。');if(a==='logout'){if(transact('退出演示账号','本机会话','用户主动退出',()=>S.authenticated=false)){$('#modal').close();go('login');}return;}
 if(a==='reset'){try{const t=F.seed();t.authenticated=S.authenticated;t.identity=S.identity;t.theme=S.theme;t.revision=S.revision+1;localStorage.setItem(KEY,JSON.stringify(t));S=t;undo=null;ui.dirty=false;$('#modal').close();render();notify('管理端拟真数据已重置');}catch(e){fail('重置未保存：'+e.message);}return;}
 let subject=id;
 const ok=transact(({publish:'发布内容',unpublish:'普通下架',force:'强制下架',rollback:'回滚发布版本','restore-publish':'恢复同版上架','media-toggle':'媒体状态变更','escalate-ticket':'升级工单','close-ticket':'关闭工单','request-refund':'申请退款','approve-refund':'财务批准退款','reject-refund':'拒绝退款','submit-refund':'提交演示退款渠道','finish-refund':'收到合成退款回执','create-risk':'举报建立风险案件','check-report':'举报核查结论','privacy-export':'开始数据导出','privacy-ready':'生成合成导出','privacy-cancel':'撤回删除申请','privacy-delete':'执行演示删除','replay-job':'恢复任务处置'})[a],subject,reason,()=>{
 if(['publish','unpublish','force','rollback','restore-publish'].includes(a)){if(who().id!=='publisher')throw Error('当前身份不能发布或下架。');const [cid,v]=id.split(':'),c=S.content.find(x=>x.id===cid);const releaseBefore=release(c);c.releaseStatus=releaseBefore;if(a==='publish'){if(c.status!=='可发布'||!c.l1||!c.l2||c.l1===c.l2||[c.l1,c.l2].includes(c.author)||!c.rights||!c.media||c.blocked.includes(c.version))throw Error('版权、媒体、同版本双签或禁供检查未通过。');c.history.push({v:c.version,title:c.title,rights:c.rights,media:c.media,l1:c.l1,l2:c.l2,date:now()});c.published=c.version;c.status='已发布';c.releaseStatus='已发布';}if(a==='unpublish'){if(release(c)!=='已发布')throw Error('目标已经不在架。');c.releaseStatus='已下架';if(!['草稿','待初审','待终审','可发布'].includes(c.status))c.status='已下架';}if(a==='force'){if(release(c)!=='已发布')throw Error('目标已经不在架。');c.blocked.push(c.published);c.releaseStatus='强制下架';if(!['草稿','待初审','待终审','可发布'].includes(c.status))c.status='强制下架';}if(a==='restore-publish'){const h=c.history.find(x=>x.v===c.published);if(release(c)!=='已下架'||!h||!h.rights||!h.media||!h.l1||!h.l2||h.l1===h.l2||c.blocked.includes(h.v))throw Error('同版发布资格失效，不能恢复。');c.releaseStatus='已发布';if(!['草稿','待初审','待终审','可发布'].includes(c.status))c.status='已发布';}if(a==='rollback'){const h=c.history.find(x=>x.v===Number(v));if(!h||!h.rights||!h.media||!h.l1||!h.l2||h.l1===h.l2||c.blocked.includes(h.v)||h.v===c.published)throw Error('选定快照不具备恢复资格。');c.published=h.v;c.releaseStatus='已发布';if(!['草稿','待初审','待终审','可发布'].includes(c.status))c.status='已发布';}event(c,({publish:'发布',unpublish:'下架',force:'强停',rollback:'回滚','restore-publish':'恢复同版'})[a]+' v'+c.published+'：'+reason);}
 if(a==='media-toggle'){const m=S.media.find(x=>x.id===id);m.status=m.status==='隔离'?'可用':'隔离';const c=S.content.find(x=>x.id===m.content);if(c&&m.status==='隔离'){c.media=false;c.l1=null;c.l2=null;c.history.forEach(h=>h.media=false);if(c.published&&!c.blocked.includes(c.published)){c.blocked.push(c.published);c.releaseStatus='强制下架';if(!['草稿','待初审','待终审','可发布'].includes(c.status))c.status='强制下架';}else if(c.status==='可发布')c.status='草稿';event(c,'媒体隔离使发布材料失效，已发布版本禁供：'+reason);}}
 if(a==='escalate-ticket'){const t=S.tickets.find(x=>x.id===id);if(t.assignee!==who().id||!['处理中','待用户补充'].includes(t.status))throw Error('工单已经变化。');if(!identities.some(x=>x.id===data.target&&x.scopes.includes('tickets'))||data.target===who().id)throw Error('请选择授权的不同接收人。');t.target=data.target;t.reason=reason;t.status='待二线接收';event(t,'升级给 '+name(data.target)+'，待接收：'+reason);}
 if(a==='close-ticket'){const t=S.tickets.find(x=>x.id===id);if(t.status!=='已解决'||!t.safe||t.assignee!==who().id)throw Error('不符合关闭条件。');t.status='已关闭';event(t,'确认解决结果后关闭');}
 if(a==='request-refund'){const o=S.orders.find(x=>x.id===id);if(S.refunds.some(r=>r.order===id)||o.status==='已退款')throw Error('此订单已有退款记录。');S.refunds.push({id:'RF-'+Date.now(),order:id,applicant:who().id,reason,approvals:[],status:'待双人审批',channel:'未提交',invoice:false});}
 if(a==='approve-refund'){const r=S.refunds.find(x=>x.id===id);if(!who().id.startsWith('finance')||r.applicant===who().id||r.approvals.includes(who().id)||r.status!=='待双人审批')throw Error('财务审批身份或状态不合法。');r.approvals.push(who().id);if(r.approvals.length===2)r.status='待渠道处理';}
 if(a==='reject-refund'){const r=S.refunds.find(x=>x.id===id);if(!who().id.startsWith('finance')||r.applicant===who().id||r.status!=='待双人审批')throw Error('只有独立财务可拒绝待审批退款。');r.status='已拒绝';r.rejectReason=reason;}
 if(a==='submit-refund'||a==='finish-refund'){const r=S.refunds.find(x=>x.id===id),o=S.orders.find(x=>x.id===r.order);if(r.approvals.length!==2)throw Error('需要两名独立财务批准。');if(a==='submit-refund'){if(r.status!=='待渠道处理')throw Error('退款状态已变化。');r.status='渠道处理中';r.channel='演示渠道已受理';o.status='退款处理中';}else{if(r.status!=='渠道处理中')throw Error('退款状态已变化。');r.status='已退款';r.channel='合成退款成功回执';o.status='已退款';o.entitlement='已回收（演示）';}}
 if(a==='create-risk'||a==='check-report'){const r=S.reports.find(x=>x.id===id);if(a==='create-risk'){if(r.risk)throw Error('该举报已经关联案件。');const rid='RK-'+Date.now();S.risks.push({id:rid,title:r.subject,source:'举报 '+id,status:'待分诊',reason,assignee:null,events:[]});r.risk=rid;r.status='已建档';}else{r.status='已核查';r.conclusion=reason;}}
 if(a.startsWith('privacy-')){const p=S.privacy.find(x=>x.id===id);if(a==='privacy-export'){if(p.type!=='数据导出'||p.status!=='待核验')throw Error('导出状态已变化。');p.status='导出准备中';}if(a==='privacy-ready'){if(p.status!=='导出准备中')throw Error('请先完成身份核验。');p.status='导出可领取';p.due=new Date(Date.now()+7*86400000).toISOString().slice(0,10);}if(a==='privacy-cancel'){if(p.status!=='冷静期')throw Error('仅冷静期可撤回。');p.status='已撤回';}if(a==='privacy-delete'){if(p.status!=='待执行'||new Date(p.due+'T00:00:00')>new Date())throw Error('删除条件未满足。');p.status='已完成';const s=S.students.find(x=>x.id===p.student);s.restricted=true;s.stage='账号已删除（演示）';}event(p,p.status+'：'+reason);}
 if(a==='replay-job'){const j=S.jobs.find(x=>x.id===id);if(j.pending){j.pending=0;j.status='恢复完成';j.last=now();}else{j.pending=1;j.status='待人工复核';}}
 });if(ok)$('#modal').close();
}
window.addEventListener('hashchange',()=>{ui.q='';ui.filter='全部';ui.page=1;ui.mode='normal';render();});
window.addEventListener('storage',e=>{if(e.key!==KEY)return;if(ui.dirty){storageFailed=true;notify('另一窗口已有新数据。当前输入保留，保存前请核对最新版本。');return;}try{if(e.newValue){S=JSON.parse(e.newValue);render();notify('已同步另一窗口的本机变更');}}catch(err){notify('无法读取窗口更新，原数据保留');}});
window.addEventListener('beforeunload',e=>{if(ui.dirty){e.preventDefault();e.returnValue='';}});
window.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();$('#list-search')?.focus();}if(e.key==='Escape'&&$('#modal').open)$('#modal').close();});
window.AdminDemo={routes:Object.keys(routes),getState:()=>clone(S),go,render};
render();
})();
